head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF08052"; // 화면 ID(원본 ULDSTF08052.xml — ETN 상장폐지 등록 팝업)
scwin.isurCd = ""; // 발행기관코드(부모 전달값 → 선택 종목의 발행회사코드로 갱신)
scwin.isurNm = ""; // 발행기관명(선택 종목의 회사명으로 갱신 — 공시안내문 대상명)
scwin.frBzProcsNo = ""; // 업무처리번호(수정·삭제 시 부모가 전달, 신규 저장 시 종목별 채번)
scwin.gubun = ""; // 발행사/기초자산 구분값(selectGubun 이 "1" 이면 종목 조회의 발행사코드)
scwin.selectGubun = ""; // 종목 선택 구분("1": 부모가 종목을 지정 → 종목선택 버튼 비활성)
scwin.selectedRow = -1; // 상장폐지종목 그리드 선택 행(-1: 미선택)
// 처리구분별 전송 정보 — key 는 $c.lc.isProcess 의 구분값(I: 저장, U: 수정, D: 삭제)
scwin.JOB_INFO = {
    I : { name : "저장", action : "/api/listing/lstproc/etn/delisting/detail/delisting/register" },
    U : { name : "수정", action : "/api/listing/lstproc/etn/delisting/detail/delisting/modify" },
    D : { name : "삭제", action : "/api/listing/lstproc/etn/delisting/detail/delisting/remove" }
};

// 버튼 역할 → 버튼 id 매핑($c.util.setButtonState 용). insert: 저장만 활성, update: 저장 외 전부 활성, error: 전부 비활성
scwin.BTN_MAP = {
    save : "btn_save",
    modify : "btn_update",
    "delete" : "btn_delete",
    guide : "btn_dscl"
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08052.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 부모 화면 파라미터 수신, 종목선택 버튼 상태, 신규(저장만 활성·발행사 종목 미리 채움)/수정(저장분 조회 후 상장폐지일 경과 여부로 버튼 상태) 분기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    // AS-IS: Provider 화면의 fn_GetPar(arrPar) 콜백으로 7개 인수를 넘겨받음 → TO-BE: 부모가 openPopup data 로 전달한 paramData
    const param = $c.data.getParameter() || {};
    scwin.isurCd = param.isurCd || ""; // 발행기관코드
    scwin.isurNm = param.isurNm || ""; // 발행기관명
    scwin.frBzProcsNo = param.bzProcsNo || ""; // 업무처리번호(수정시만 유효)
    scwin.gubun = param.gubun || ""; // 발행사/기초자산 구분값
    scwin.selectGubun = param.selectGubun || ""; // 종목 선택 구분값
    // secugrpId(증권그룹ID)·mktId(시장구분코드)도 전달되지만 이 화면에서는 사용하지 않는다.

    scwin.setIsuCdBtnShow(scwin.selectGubun);

    if ($c.util.isEmpty(scwin.frBzProcsNo)) {
        // 신규작성 — 저장만 활성
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        if (scwin.selectGubun === "1") {
            await scwin.searchEtnCode(); // 부모가 지정한 발행사의 ETN 종목을 미리 채운다
        }
    } else {
        // 수정 — 저장분 조회 후 상장폐지일이 지났으면 전부 비활성(error), 아니면 저장 외 활성(update)
        await scwin.search();
        $c.stf.setButtonSetWithDate(edt_DelistDd, false, "grpBtnBox", scwin.BTN_MAP);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_SetIsuCd_onclick
 * @description 종목선택 — 「종목선택」 클릭 이벤트(ETN 종목선택 팝업에서 고른 종목 목록으로 그리드를 채운다)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        const result = await scwin.openIsuSelectPopup();
        // 팝업은 고른 종목 목록(배열)을 돌려준다. 한 건만 돌려주는 팝업이면 배열로 감싼다.
        // 취소·X 닫기는 { isCloseButtonClick } 객체가 오므로 종목코드 유무로 판정한다.
        const rows = Array.isArray(result) ? result : ((result && !$c.util.isEmpty(result.isuCd)) ? [result] : []);
        if (rows.length === 0) return;

        dlt_isuTemp.setJSON(rows); // AS-IS fn_SetParIsu 와 같이 행 선택은 하지 않는다
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08052.img_SetIsuCd_onclick" });
    }
};

/**
 * @method
 * @name img_DELIST_RSN_DSC_onclick
 * @description 상장폐지사유 검색 — 사유선택 팝업 결과(코드·사유명·근거규정)를 dma_mst 에 반영
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_DELIST_RSN_DSC_onclick = async function (e) {
    try {
        const result = await scwin.openDelistRsnPopup();
        if ($c.util.isEmpty(result) || $c.util.isEmpty(result.code)) return;

        dma_mst.set("delistRsnCd", result.code);
        dma_mst.set("delistRsnDsc", result.name);
        dma_mst.set("grndRegulNm", result.regl);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08052.img_DELIST_RSN_DSC_onclick" });
    }
};

/**
 * @method
 * @name btn_dscl_onclick
 * @description 안내문작성 — 「안내문작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_dscl_onclick = async function (e) {
    try {
        await scwin.dscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08052.btn_dscl_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 삭제 — 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08052.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name btn_update_onclick
 * @description 수정 — 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08052.btn_update_onclick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 저장 — 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08052.btn_save_onclick" });
    }
};

/**
 * @method
 * @name edt_DelistDd_onchange
 * @description 상장폐지일 변경 — 기타(안내문구) 초기화
 * @param {Object} info 이벤트 정보 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edt_DelistDd_onchange = async function (info) {
    try {
        dma_mst.set("remk", "");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08052.edt_DelistDd_onchange" });
    }
};

/**
 * @method
 * @name MxGrid_2_oncellclick
 * @description 상장폐지종목 그리드 셀 클릭 — 선택 행 보관(안내문작성 대상)
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxGrid_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        scwin.selectGridRow(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08052.MxGrid_2_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 저장된 상장폐지 내용 조회(수정 모드) — 마스터(dma_mst)·종목 목록(dlt_isuTemp)을 업무처리번호로 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    // AS-IS: dts_Mst.DataID = "/Delisting.do?method=searchDelList&DIV_IDX=" + DIV_IDX_DELLIST_MST + "&BZ_PROCS_NO=" + fr_bz_procs_no
    //        dts_Isu.DataID = "/etn/EtnMktAct.do?method=searchDelist&DIV_IDX=" + DIV_IDX_ETN_DELLIST_DTL + "&BZ_PROCS_NO=" + fr_bz_procs_no
    // TODO Stage2: 상장폐지 조회 REST 엔드포인트·응답 키(mst/isuList) 확정 시 action·target 교체(저장 계열 /api/listing/lstproc/etn/delisting/detail/delisting/* 와 짝)
    const requestMap = {
        bzProcsNo : scwin.frBzProcsNo
    };
    const sbmOptions = {
        id : "sbm_search",
        action : "/api/listing/lstproc/etn/delisting/detail/delisting",
        method : "get",
        target : "dma_mst=body.mst,dlt_isuTemp=body.isuList",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, requestMap);
    if (res && res.skipped) return; // 중복 제출 skip 응답은 무시
    // AS-IS 는 조회 후 행을 선택하지 않는다(안내문작성 대상은 사용자가 클릭해 선택)
};

/**
 * @method
 * @name searchEtnCode
 * @description 부모가 지정한 발행사의 ETN 종목 조회(selectGubun 이 "1" 인 신규작성) — 결과로 상장폐지종목 그리드를 채운다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchEtnCode = async function () {
    // AS-IS: dts_Isu.DataID = "/etn/EtnCodeAct.do?method=searchEtnCode&GUBUN=" + select_gubun + "&ISUR_CD=" + gubun
    // TODO Stage2: ETN 종목 조회 REST 엔드포인트 확정 시 action 교체
    const requestMap = {
        gubun : scwin.selectGubun,
        isurCd : scwin.gubun // AS-IS ISUR_CD 파라미터 — 부모(jldstf08051 getParNew)는 selectGubun "1" 이면 종목코드를 gubun 자리에 넘긴다
    };
    const sbmOptions = {
        id : "sbm_searchEtnCode",
        action : "/api/listing/lstproc/etn/delisting/detail/etn-code",
        method : "get",
        target : "dlt_isuTemp",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, requestMap);
    if (res && res.skipped) return; // 중복 제출 skip 응답은 무시
    // AS-IS 는 조회 후 행을 선택하지 않는다(안내문작성 대상은 사용자가 클릭해 선택)
};

/**
 * @method
 * @name checkDuplicate
 * @description 중복 체크 — 그리드의 종목마다 같은 상장폐지일에 이미 상장폐지된 종목이 있는지 서버 확인(수정 시 자기 건은 제외)
 * @param {Boolean} isUpdate 수정 여부(true 면 업무처리번호를 함께 보내 자기 건 제외)
 * @returns {Promise<Boolean>} 중복 없음 true, 중복 있음·통신 실패 false
 * @hidden N
 */
scwin.checkDuplicate = async function (isUpdate) {
    // AS-IS: dts_DupIsu.DataID = "/Delisting.do?method=searchDupDelist&ISU_CD=…&DELIST_DD=…[&BZ_PROCS_NO=…]" (첫 종목만 검사)
    const delistDd = edt_DelistDd.getValue();
    const rowCount = dlt_isuTemp.getRowCount();

    for (let i = 0; i < rowCount; i++) {
        const isuCd = dlt_isuTemp.getCellData(i, "isuCd");
        const requestMap = {
            isuCd : isuCd,
            delistDd : delistDd
        };
        if (isUpdate) {
            requestMap.bzProcsNo = dlt_isuTemp.getCellData(i, "bzProcsNo");
        }
        const sbmOptions = {
            id : "sbm_checkDuplicate",
            action : "/api/listing/lstproc/etn/delisting/detail/isDuplicate",
            method : "get",
            isProcessMsg : false
        };
        const res = await $c.sbm.executeDynamic(sbmOptions, requestMap);
        if (res && res.skipped) return false; // 중복 제출 skip 응답은 무시
        if (!res.responseJSON.success) return false;

        // 응답 본문은 중복 종목 배열·중복 종목 객체({ isuCd })·중복 여부(true/false) 를 모두 허용한다(엔드포인트 미확정, AS-IS 는 행 집합)
        const body = res.responseJSON.body;
        let dupIsuCd = "";
        if (Array.isArray(body)) {
            dupIsuCd = body.length > 0 ? (body[0].isuCd || isuCd) : "";
        } else if ($c.util.isPlainObject(body)) {
            dupIsuCd = body.isuCd;
        } else if (body === true) {
            dupIsuCd = isuCd;
        }
        if ($c.util.isNotEmpty(dupIsuCd)) {
            await $c.win.alert("동일한 날짜에 상장폐지된 종목[" + dupIsuCd + "]이 존재합니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name saveTrs
 * @description 저장/수정/삭제 1건 전송 — dma_mst(종목 1건이 옮겨진 상태)를 처리구분별 엔드포인트로 전송
 * @param {Object} job 처리 정보(scwin.JOB_INFO 의 항목 — name/action)
 * @returns {Promise<Boolean>} 전송 성공 여부
 * @hidden N
 */
scwin.saveTrs = async function (job) {
    // AS-IS: trs.Action = "/etn/EtnMktAct.do?method=saveDelist&…", trs.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)", trs.Post()
    // ETN 은 항상 종목별 기준으로 처리한다(1: 종목별, 2: 법인별)
    dma_mst.set("mktactApplObjTpCd", "1");

    const sbmOptions = {
        id : "sbm_save",
        action : job.action,
        method : "post",
        ref : "dma_mst",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) return false; // 중복 제출 skip 응답은 무시

    return res.responseJSON.success === true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name processJob
 * @description 저장/수정/삭제 공통 전송 루프 — 종목마다 업무처리번호를 정하고(저장: 채번, 수정·삭제: 행의 번호) dma_mst 에 옮겨 1건씩 전송한다. AS-IS 의 trs 응답 카운터(trsCnt/trsTotalCnt/trsErrCnt)는 순차 await 로 대체
 * @param {String} jobKey 처리구분(I: 저장, U: 수정, D: 삭제)
 * @returns {Promise<Object>} { okCnt: 성공 건수, errCnt: 실패 건수, doneRows: 성공 행 인덱스 배열 }
 * @hidden N
 */
scwin.processJob = async function (jobKey) {
    const job = scwin.JOB_INFO[jobKey];
    const rowCount = dlt_isuTemp.getRowCount();
    const result = { okCnt : 0, errCnt : 0, doneRows : [] };

    for (let i = 0; i < rowCount; i++) {
        if (jobKey === "I") {
            // 종목별로 새 업무처리번호 채번 — pcc getNewBzProcNo 는 responseJSON 을 그대로 돌려주므로 { body } 봉투면 body 를 꺼낸다
            const newNo = await $c.stf.getNewBzProcNo();
            scwin.frBzProcsNo = String(($c.util.isPlainObject(newNo) && newNo.body !== undefined) ? newNo.body : newNo);
            if (scwin.frBzProcsNo.length !== 14) {
                await $c.win.alert($c.stf.getMessageParam("MSG-0010", "")); // 업무처리번호생성실패
                result.errCnt++;
                continue;
            }
        } else {
            scwin.frBzProcsNo = dlt_isuTemp.getCellData(i, "bzProcsNo");
        }

        scwin.copyToMst(i);
        if (await scwin.saveTrs(job)) {
            dlt_isuTemp.setCellData(i, "bzProcsNo", scwin.frBzProcsNo);
            result.okCnt++;
            result.doneRows.push(i);
        } else {
            result.errCnt++;
        }
    }
    return result;
};

/**
 * @method
 * @name finishJob
 * @description 저장/수정/삭제 후처리 — 성공(MSG-A001)/실패(MSG-A002) 알림, 성공 건이 있으면 부모 목록 재조회, 삭제는 전건 성공 시 팝업 닫기(일부 실패면 삭제된 행만 제거), 저장은 1건이라도 성공하면 수정 모드 전환(종목선택 비활성·날짜 규칙 버튼 상태), 종목이 1건이면 그 행 선택
 * @param {String} jobKey 처리구분(I: 저장, U: 수정, D: 삭제)
 * @param {Object} result processJob 결과 { okCnt, errCnt, doneRows }
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.finishJob = async function (jobKey, result) {
    const jobNm = scwin.JOB_INFO[jobKey].name;

    if (result.errCnt > 0) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm)); // "[처리명] 처리 실패하였습니다."
    } else {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm)); // "[처리명] 처리 성공하였습니다."
    }
    if (result.okCnt > 0) {
        await scwin.refreshParent(); // 성공 건이 있으면 부모 목록 재조회
    }

    if (jobKey === "D") {
        if (result.errCnt === 0) {
            $c.win.closePopup(); // 전건 삭제되면 팝업 닫기
            return;
        }
        dlt_isuTemp.removeRows(result.doneRows); // 일부만 삭제되면 삭제된 행만 그리드에서 제거(AS-IS trs_OnFail 의 status "Y" 행 제거)
    } else if (jobKey === "I" && result.okCnt > 0) {
        // 1건이라도 저장되면 수정 모드로 전환 — 종목 추가 불가, 상장폐지일 경과 여부로 버튼 상태(AS-IS dts_Mst_OnLoadCompleted 와 같은 규칙)
        scwin.setIsuCdBtnShow("1");
        $c.stf.setButtonSetWithDate(edt_DelistDd, false, "grpBtnBox", scwin.BTN_MAP);
    }

    // 종목마다 업무처리번호가 다르므로 search(1건 기준)로 재조회하지 않고 processJob 이 그리드에 적어 둔 bzProcsNo 를 그대로 쓴다
    // AS-IS trs_OnSuccess: 종목이 1건이면 그 행을 선택, 아니면 선택 해제
    scwin.selectedRow = -1;
    if (dlt_isuTemp.getRowCount() === 1) {
        scwin.selectGridRow(0);
    }
};

/**
 * @method
 * @name checkForm
 * @description 유효성 체크 — 상장폐지종목 선택 여부 확인 후 상장폐지사유·상장폐지일(날짜)·근거규정(200byte)·기타(2000byte)를 validateDataCollect 로 검증
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.checkForm = async function () {
    if (dlt_isuTemp.getRowCount() === 0) {
        await $c.win.alert("[상장폐지종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }

    // AS-IS: checkEmptyValue(상장폐지사유) → checkDdTm("DD", 상장폐지일) → checkEmptyValue(근거규정) → checkMaxLength(근거규정 200) → checkMaxLength(기타 2000)
    // 길이 상한은 maxLengthB(UTF-8 byte, 한글 3byte) — AS-IS checkMaxLength 는 한글 2byte 였으므로 DB 컬럼 byte 기준 확인(TODO Stage2)
    const options = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txb_DELIST_RSN_DSC : { required : true, name : "상장폐지사유" },
            edt_DelistDd : { required : true, format : "date", name : "상장폐지일" },
            txb_GrndRegulNm : { required : true, maxLengthB : 200, name : "근거규정" },
            txa_Remk : { maxLengthB : 2000, name : "기타" }
        }
    };
    return await $c.validate.validateDataCollect(grp_table, options);
};

/**
 * @method
 * @name copyToMst
 * @description 그리드 종목 1건을 저장 DataMap(dma_mst) 에 옮기고 선택 종목의 발행회사코드·회사명을 보관
 * @param {Number} index 그리드 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.copyToMst = function (index) {
    dma_mst.set("bzProcsNo", scwin.frBzProcsNo);
    dma_mst.set("isuCd", dlt_isuTemp.getCellData(index, "isuCd"));
    dma_mst.set("isuNm", dlt_isuTemp.getCellData(index, "isuNm"));
    dma_mst.set("isurCd", dlt_isuTemp.getCellData(index, "isurCd"));
    dma_mst.set("isurNm", dlt_isuTemp.getCellData(index, "isurNm"));
    dma_mst.set("comNm", dlt_isuTemp.getCellData(index, "comNm"));
    dma_mst.set("lsttrdDd", dlt_isuTemp.getCellData(index, "lsttrdDd"));
    dma_mst.set("expDd", dlt_isuTemp.getCellData(index, "expDd"));
    scwin.isurCd = dlt_isuTemp.getCellData(index, "isurCd");
    scwin.isurNm = dlt_isuTemp.getCellData(index, "comNm");
};

/**
 * @method
 * @name save
 * @description 저장 — 유효성·중복 체크, 처리 확인 후 종목별 저장 전송
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkForm()) return;
    if (!await scwin.checkDuplicate(false)) return;
    if (!await $c.lc.isProcess("I")) return;

    const result = await scwin.processJob("I");
    await scwin.finishJob("I", result);
};

/**
 * @method
 * @name update
 * @description 수정 — 유효성·중복 체크(자기 건 제외), 처리 확인 후 종목별 수정 전송
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    if (!await scwin.checkForm()) return;
    if (!await scwin.checkDuplicate(true)) return;
    if (!await $c.lc.isProcess("U")) return;

    const result = await scwin.processJob("U");
    await scwin.finishJob("U", result);
};

/**
 * @method
 * @name remove
 * @description 삭제 — 처리 확인 후 종목별 삭제 전송(완료 시 팝업 닫힘)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.remove = async function () {
    if (!await $c.lc.isProcess("D")) return;

    const result = await scwin.processJob("D");
    await scwin.finishJob("D", result);
};

/**
 * @method
 * @name dscl
 * @description 안내문작성 — 선택 종목을 dma_mst 에 옮긴 뒤 공시안내문작성 팝업(ULDSTF92024)을 연다. 팝업이 부모의 getPar(arr, 종목 DataList, 마스터 DataMap) 를 이름으로 불러 참조로 채워 가는 레거시 계약을 유지하고, 같은 내용을 openPopup data 로도 넘긴다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function () {
    if (scwin.selectedRow < 0) {
        await $c.win.alert("종목을 선택해 주세요!");
        return;
    }
    scwin.copyToMst(scwin.selectedRow);
    const isuNm = dlt_isuTemp.getCellData(scwin.selectedRow, "isuNm");
    const comNm = dlt_isuTemp.getCellData(scwin.selectedRow, "comNm");

    // TODO Stage2: ULDSTF92024 전환본 확정 시 getPar/setPar 계약을 data 전달로 일원화
    const oldGetPar = scwin.getPar;
    const oldSetPar = scwin.setPar;
    scwin.getPar = function (arr, paramDltIsu, paramDmaMst) {
        arr[0] = "68351"; // 공시 서식코드
        arr[1] = scwin.frBzProcsNo;
        arr[2] = scwin.isurCd;
        arr[3] = "1";
        arr[5] = isuNm; // arr[4] 는 안내문 내용(ctnt) 자리 — 미사용

        if (paramDltIsu && typeof paramDltIsu.setJSON === "function") {
            paramDltIsu.setJSON(dlt_isuTemp.getAllJSON());
        }
        if (paramDmaMst && typeof paramDmaMst.setJSON === "function") {
            paramDmaMst.setJSON(dma_mst.getJSON());
            paramDmaMst.set("tgtNm", scwin.isurNm);
            paramDmaMst.set("delistRsnNm", dma_mst.get("delistRsnDsc"));
            paramDmaMst.set("comNm", comNm);
        }
        return arr.length;
    };
    scwin.setPar = function (arr) {
        // 공시안내문작성 팝업은 반환값이 없다
    };

    const data = {
        formCd : "68351",
        bzProcsNo : scwin.frBzProcsNo,
        isurCd : scwin.isurCd,
        mktactApplObjTpCd : "1",
        isuNm : isuNm,
        tgtNm : scwin.isurNm,
        delistRsnNm : dma_mst.get("delistRsnDsc"),
        comNm : comNm,
        mst : dma_mst.getJSON(),
        isuList : dlt_isuTemp.getAllJSON()
    };
    const options = {
        id : "ULDSTF92024",
        title : "공시안내문작성",
        type : "pageFramePopup",
        width : 745,
        height : 825
    };
    try {
        // AS-IS: $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, 745, 825, "window")
        await $c.win.openPopup("/ui/lst/common/ULDSTF92024.xml", options, data);
    } finally {
        scwin.getPar = oldGetPar;
        scwin.setPar = oldSetPar;
    }
};

/**
 * @method
 * @name refreshParent
 * @description 부모 화면(ETN 상장폐지 목록) 재조회 — 부모의 search 호출(AS-IS fn_search 는 규칙 13 개명으로 search)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.refreshParent = async function () {
    // AS-IS: $c.frame.path("../").fn_search() → 팝업 타입(pageFramePopup/browserPopup) 무관하게 opener scope 로 접근
    // 부모 전환본 jsp-front/ui-tobe/jldstf08051.xml: 탭1 재조회 함수는 scwin.search, 파라미터는 getParNew/getParUpdate 의
    // arrPar[0..6] = isurCd/isurNm/secugrpId/mktId/bzProcsNo/gubun/selectGubun → paramData 키로 받는다
    // TODO Stage2: 부모 newCreateFrame 이 아직 전환 미완(throw) — openPopup(data) 전환 시 위 키 이름으로 맞출 것
    const openerScope = $c.win.getOpenerScope();
    if ($c.util.isEmpty(openerScope) || $c.util.isEmpty(openerScope.scwin) || typeof openerScope.scwin.search !== "function") return;

    await openerScope.scwin.search();
};

/**
 * @method
 * @name setIsuCdBtnShow
 * @description 종목선택 버튼 활성 여부 — 부모가 종목을 지정했거나("1") 수정 모드(업무처리번호 있음)면 비활성
 * @param {String} initTyp 종목 선택 구분값
 * @returns {void}
 * @hidden N
 */
scwin.setIsuCdBtnShow = function (initTyp) {
    img_SetIsuCd.setDisabled(initTyp === "1" || !$c.util.isEmpty(scwin.frBzProcsNo));
};

/**
 * @method
 * @name selectGridRow
 * @description 그리드 행 선택 — 선택 행 인덱스와 그 행의 발행회사코드·업무처리번호를 보관
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.selectGridRow = function (row) {
    scwin.selectedRow = row;
    scwin.isurCd = dlt_isuTemp.getCellData(row, "isurCd");
    const rowBzProcsNo = dlt_isuTemp.getCellData(row, "bzProcsNo");
    if ($c.util.isNotEmpty(rowBzProcsNo)) {
        scwin.frBzProcsNo = rowBzProcsNo; // 행에 번호가 없으면(신규·조회 응답 미포함) 부모 전달값을 유지한다
    }
};

/**
 * @method
 * @name openIsuSelectPopup
 * @description ETN 종목선택 팝업(ULDSTF08045) 열기 — 선택 종목 행 배열을 반환값으로 받는다
 * @returns {Promise<Array|Object>} 선택 종목 목록(취소·X 닫기면 { isCloseButtonClick })
 * @hidden N
 */
scwin.openIsuSelectPopup = async function () {
    // AS-IS: $c.lce.fn_PopFindEtnCode() → CreateDialogFrame("DLG_ETN_CODE", "../etn/ULDSTF08045.gfm", "종목선택", 10, 10, 520, 440, "window")
    //        + 부모 fn_GetParIsu(arr, dts)(arr[0]=발행기관코드, arr[1]=선택구분, 현재 종목 DataSet 복사) / fn_SetParIsu(dts)(선택 종목 DataSet 복사) 계약
    // TO-BE: ETN 종목선택 공통(list_common_etn)이 pcc/stf 에 아직 없어 화면에서 pageFramePopup 으로 직접 열고 반환값으로 받는다.
    // TODO Stage2: ULDSTF08045 전환본 확정 시 반환 형태(종목 행 배열) 대조, pcc 반입 시 $c.lc.popFindEtnCode 로 교체
    const options = {
        id : "ULDSTF08045",
        title : "종목선택",
        type : "pageFramePopup",
        width : 520,
        height : 440
    };
    const data = {
        isurCd : scwin.isurCd,
        gubun : scwin.selectGubun,
        isuList : dlt_isuTemp.getAllJSON()
    };
    return await $c.win.openPopup("/ui/lst/etn/ULDSTF08045.xml", options, data);
};

